answer:
class Stack<T> {
  private store: T[] = [];
  push(v: T): void { this.store.push(v); }
  pop(): T | undefined { return this.store.pop(); }
  peek(): T | undefined { return this.store[this.store.length - 1]; }
  size(): number { return this.store.length; }
}
